import { revalidatePath } from 'next/cache';
import { cookies } from 'next/headers';

async function toggleNotifications() {
  'use server';

  const store = await cookies();
  const current = store.get('notifications')?.value === 'on';
  const nextValue = current ? 'off' : 'on';

  store.set('notifications', nextValue, { path: '/' });
  revalidatePath('/');
}

export default async function Home() {
  const store = await cookies();
  const notificationsEnabled =
    store.get('notifications')?.value === 'on';

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{notificationsEnabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn {notificationsEnabled ? 'off' : 'on'} notifications
        </button>
      </form>
    </main>
  );
}
